"""Comprehensive tests for synthstr.stringy module."""

from __future__ import annotations

import pytest

from synthstr.stringy import is_palindrome, reverse, truncate, word_count


# ---------------------------------------------------------------------------
# reverse
# ---------------------------------------------------------------------------


class TestReverse:
    def test_empty_string(self):
        assert reverse("") == ""

    def test_single_character(self):
        assert reverse("x") == "x"

    def test_simple_word(self):
        assert reverse("hello") == "olleh"

    def test_palindrome_word(self):
        assert reverse("racecar") == "racecar"

    def test_with_spaces(self):
        assert reverse("a b c") == "c b a"

    def test_unicode(self):
        assert reverse("café") == "éfac"

    def test_emoji(self):
        # Individual code-point reversal
        assert reverse("ab\U0001f600") == "\U0001f600ba"

    def test_numeric_string(self):
        assert reverse("12345") == "54321"


# ---------------------------------------------------------------------------
# is_palindrome
# ---------------------------------------------------------------------------


class TestIsPalindrome:
    def test_empty_string(self):
        assert is_palindrome("") is True

    def test_single_character(self):
        assert is_palindrome("a") is True

    def test_simple_palindrome(self):
        assert is_palindrome("racecar") is True

    def test_not_palindrome(self):
        assert is_palindrome("hello") is False

    def test_ignores_case(self):
        assert is_palindrome("RaceCar") is True

    def test_ignores_non_alnum(self):
        assert is_palindrome("A man, a plan, a canal: Panama") is True

    def test_with_numbers(self):
        assert is_palindrome("12321") is True

    def test_numbers_not_palindrome(self):
        assert is_palindrome("12345") is False

    def test_mixed_alnum_palindrome(self):
        assert is_palindrome("Was it a car or a cat I saw?") is True

    def test_spaces_only(self):
        # No alnum chars -> empty cleaned -> palindrome
        assert is_palindrome("   ") is True

    def test_punctuation_only(self):
        assert is_palindrome("!!!") is True


# ---------------------------------------------------------------------------
# word_count
# ---------------------------------------------------------------------------


class TestWordCount:
    def test_empty_string(self):
        assert word_count("") == 0

    def test_single_word(self):
        assert word_count("hello") == 1

    def test_multiple_words(self):
        assert word_count("one two three") == 3

    def test_leading_trailing_spaces(self):
        assert word_count("  hello world  ") == 2

    def test_multiple_spaces_between(self):
        assert word_count("a   b   c") == 3

    def test_tabs_and_newlines(self):
        assert word_count("a\tb\nc") == 3

    def test_only_whitespace(self):
        assert word_count("   \t\n  ") == 0


# ---------------------------------------------------------------------------
# truncate
# ---------------------------------------------------------------------------


class TestTruncate:
    def test_no_truncation_needed(self):
        assert truncate("hi", 10) == "hi"

    def test_exact_limit(self):
        assert truncate("hello", 5) == "hello"

    def test_truncation_adds_ellipsis(self):
        result = truncate("hello world", 6)
        assert result == "hello\u2026"
        assert len(result) == 6

    def test_limit_one(self):
        assert truncate("hello", 1) == "\u2026"

    def test_limit_zero(self):
        assert truncate("hello", 0) == ""

    def test_empty_string_limit_zero(self):
        assert truncate("", 0) == ""

    def test_empty_string_positive_limit(self):
        assert truncate("", 5) == ""

    def test_negative_limit_raises(self):
        with pytest.raises(ValueError, match="limit must be non-negative"):
            truncate("hello", -1)

    def test_result_never_exceeds_limit(self):
        for limit in range(0, 20):
            result = truncate("a long string for testing", limit)
            assert len(result) <= limit

    def test_unicode_content(self):
        result = truncate("café latte", 5)
        assert len(result) == 5
        assert result[-1] == "\u2026"

